class Solution { public List<Integer> goodIndices(int[] nums,int k){int n=nums.length;int[] left=new int[n],right=new int[n];left[0]=1;for(int i=1;i<n;i++)left[i]=nums[i]<=nums[i-1]?left[i-1]+1:1;right[n-1]=1;for(int i=n-2;i>=0;i--)right[i]=nums[i]<=nums[i+1]?right[i+1]+1:1;List<Integer> answer=new ArrayList<>();for(int i=k;i<n-k;i++)if(left[i-1]>=k&&right[i+1]>=k)answer.add(i);return answer;} }
